36	namespace xls::dslx {
37	
38	// Simple visitor to perform automatic dispatch to constexpr evaluate AST
39	// expressions.
40	//
41	// Note that WarningCollector is given as a pointer and not a reference because
42	// it is optional; e.g. sometimes constexpr evaluation is performed during IR
43	// conversion, at which point we don't want to be collecting warnings since we
44	// expect to have flagged all warnings (e.g. rollovers) in the type checking
45	// phase.
46	class ConstexprEvaluator : public xls::dslx::ExprVisitor {
47	 public:
48	  // Evaluates the given expression to determine if it's constexpr or not, and
49	  // updates `type_info` accordingly. Returns success as long as no error
50	  // occurred during evaluation, even if `expr` is non-constexpr.
51	  static absl::Status Evaluate(ImportData* import_data, TypeInfo* type_info,
52	                               WarningCollector* warning_collector,
53	                               const ParametricEnv& bindings, const Expr* expr,
54	                               const Type* type = nullptr,
55	                               bool warn_rollover = false);
56	
57	  // Performs the same action as `Evaluate`, but returns the resulting constexpr
58	  // value. Returns an error status if `expr` is non-constexpr.
59	  static absl::StatusOr<InterpValue> EvaluateToValue(
60	      ImportData* import_data, TypeInfo* type_info,
61	      WarningCollector* warning_collector, const ParametricEnv& bindings,
62	      const Expr* expr, bool warn_rollover = false);
63	
64	  // A concrete type is only necessary when:
65	  //  - Deducing a Number that is undecorated and whose type is specified by
66	  //    context, e.g., an element in a constant array:
67	  //    `u32[4]:[0, 1, 2, 3]`. It can be nullptr in all other circumstances.
68	  //  - Deducing a constant array whose declaration terminates in an ellipsis:
69	  //    `u32[4]:[0, 1, ...]`. The type is needed to determine the number of
70	  //    elements to fill in.
71	  // In all other cases, `type` can be nullptr.
72	  ~ConstexprEvaluator() override = default;
73	
74	  absl::Status HandleAllOnesMacro(const AllOnesMacro* expr) override;
75	  absl::Status HandleArray(const Array* expr) override;
76	  absl::Status HandleAttr(const Attr* expr) override;
77	  absl::Status HandleBinop(const Binop* expr) override;
78	  absl::Status HandleCast(const Cast* expr) override;
79	  absl::Status HandleChannelDecl(const ChannelDecl* expr) override;
80	  absl::Status HandleColonRef(const ColonRef* expr) override;
81	  absl::Status HandleConditional(const Conditional* expr) override;
82	  absl::Status HandleFor(const For* expr) override;
83	  absl::Status HandleFormatMacro(const FormatMacro* expr) override {
84	    return absl::OkStatus();
85	  }
86	  absl::Status HandleFunctionRef(const FunctionRef* expr) override;
87	  absl::Status HandleIndex(const Index* expr) override;
88	  absl::Status HandleInvocation(const Invocation* expr) override;
89	  absl::Status HandleLambda(const Lambda* expr) override;
90	  absl::Status HandleMatch(const Match* expr) override;
91	  absl::Status HandleNameRef(const NameRef* expr) override;
92	  absl::Status HandleNumber(const Number* expr) override;
93	  absl::Status HandleRange(const Range* expr) override;
94	  absl::Status HandleSpawn(const Spawn* expr) override {
95	    return absl::OkStatus();
96	  }
97	  absl::Status HandleSplatStructInstance(
98	      const SplatStructInstance* expr) override;
99	  absl::Status HandleStatementBlock(const StatementBlock* expr) override;
100	  absl::Status HandleString(const String* expr) override;
101	  absl::Status HandleStructInstance(const StructInstance* expr) override;
102	  absl::Status HandleTupleIndex(const TupleIndex* expr) override;
103	  absl::Status HandleUnop(const Unop* expr) override;
104	  absl::Status HandleConstFor(const ConstFor* expr) override;
105	  absl::Status HandleVerbatimNode(const VerbatimNode* node) override;
106	  absl::Status HandleXlsTuple(const XlsTuple* expr) override;
107	  absl::Status HandleZeroMacro(const ZeroMacro* expr) override;
108	
109	 private:
110	  absl::Status HandleExternRef(const NameRef* name_ref, const NameDef* name_def,
111	                               UseTreeEntry* use_tree_entry);
112	
113	  ConstexprEvaluator(ImportData* import_data, TypeInfo* type_info,
114	                     WarningCollector* warning_collector,
115	                     ParametricEnv bindings, const Type* type,
116	                     bool warn_rollover)
117	      : import_data_(import_data),
118	        type_info_(type_info),
119	        warning_collector_(warning_collector),
120	        bindings_(std::move(bindings)),
121	        type_(type),
122	        warn_rollover_(warn_rollover) {}
123	
124	  // Interprets the given expression. Prior to calling this function, it's
125	  // necessary to determine that all expression components are constexpr.
126	  absl::Status InterpretExpr(const Expr* expr);
127	
128	  ImportData* const import_data_;
129	  TypeInfo* const type_info_;
130	  WarningCollector* const warning_collector_;
131	  const ParametricEnv bindings_;
132	  const Type* const type_;
133	  bool warn_rollover_;
134	};
135	
136	// Holds the results of `MakeConstexprEnv()` -- generally users will use `env`,
137	// but `freevars` and `non_constexpr` provide useful information in cases where
138	// something goes wrong or needs to be reported via error messages.
139	struct ConstexprEnvData {
140	  // Free variables for the given expression.
141	  FreeVariables freevars;
142	
143	  // Constexpr environment we were able to construct.
144	  //
145	  // Note that it seems ok for now for the keys to be std::string rather than
146	  // NameDef* because we only use this map in the context of a single
147	  // expression, and free variables from the expression for a given identifier
148	  // will all point to the same thing, there is no partial shadowing that can
149	  // occur.
150	  absl::flat_hash_map<std::string, InterpValue> env;
151	
152	  // Free variable references that we were unable to resolve to a constexpr
153	  // value.
154	  //
155	  // Note that this can include things like references to imported modules,
156	  // as those are not themselves constexpr.
157	  absl::flat_hash_set<const NameRef*> non_constexpr;
158	};
159	
160	// Creates a map of `{symbol_name: value}` for all known symbols in the required
161	// environment for `env`.
162	//
163	// This will be populated with parametric bindings as well as
164	// constexpr freevars of `node`, which is useful when there are local
165	// const bindings closed over e.g. in function scope.
166	//
167	// `type_info` is required to look up the value of previously computed
168	// constexprs.
169	absl::StatusOr<ConstexprEnvData> MakeConstexprEnv(
170	    ImportData* import_data, TypeInfo* type_info,
171	    WarningCollector* warning_collector, const Expr* node,
172	    const ParametricEnv& parametric_env);
173	
174	// Returns a helpful text representation fo the given environment map, suitable
175	// for putting into error messages and similar, along the lines of:
176	//
177	//    {MOL: u32:42, TWO: u32:2}
178	//
179	// Note the returned string is deterministic.
180	std::string EnvMapToString(
181	    const absl::flat_hash_map<std::string, InterpValue>& map);
182	
183	// Evaluates a Number AST node to an InterpValue.
184	absl::StatusOr<InterpValue> EvaluateNumber(const Number& expr,
185	                                           const Type& type);
186	
187	// Evaluates a format string with constexpr arguments to a string.
188	absl::StatusOr<std::string> EvaluateFormatString(
189	    ImportData* import_data, TypeInfo* type_info,
190	    WarningCollector* warning_collector, const ParametricEnv& parametric_env,
191	    const std::vector<FormatStep>& steps, absl::Span<Expr* const> args);
192	
193	// Formats an InterpValue to a string according to format preference.
194	absl::StatusOr<std::string> FormatInterpValue(const InterpValue& value,
195	                                              FormatPreference preference);
196	
197	}  // namespace xls::dslx
198	
199	#endif  // XLS_DSLX_CONSTEXPR_EVALUATOR_H_
