15	fn const_for_mask<N: u32>() -> u8 {
16	    const for (idx, mask): (u32, u8) in u32:0..N {
17	        mask | (u8:1 << idx)
18	    }(u8:0)
19	}
20	
21	#[test]
22	fn const_for_test() {
23	    assert_eq(const_for_mask<u32:5>(), u8:0b11111);
24	    assert_eq(const_for_mask<u32:8>(), u8::MAX);
25	}
26	
27	fn main() -> u8 { const_for_mask<u32:3>() }
28	
29	proc ConstForInst {
30	    req_r: chan<()> in;
31	    resp_s: chan<u32> out;
32	
33	    config(req_r: chan<()> in, resp_s: chan<u32> out) { (req_r, resp_s) }
34	
35	    init {  }
36	
37	    next(_: ()) {
38	        let (tok, _d) = recv(join(), req_r);
39	        let result = const for (idx, mask): (u32, u32) in u32:0..u32:5 {
40	            mask | (u32:1 << idx)
41	        }(u32:0);
42	        let tok = send(tok, resp_s, result);
43	    }
44	}
45	
46	const NUM_OF_CHANNELS = u32:2;
47	
48	#[test_proc]
49	proc ConstForProcSpawnTest {
50	    req_s: chan<()>[NUM_OF_CHANNELS] out;
51	    resp_r: chan<u32>[NUM_OF_CHANNELS] in;
52	    terminator: chan<bool> out;
53	
54	    config(terminator: chan<bool> out) {
55	        let (req_s, req_r) = chan<()>[NUM_OF_CHANNELS]("req");
56	        let (resp_s, resp_r) = chan<u32>[NUM_OF_CHANNELS]("resp");
57	        const for (idx, _): (u32, ()) in u32:0..NUM_OF_CHANNELS {
58	            spawn ConstForInst(req_r[idx], resp_s[idx]);
59	        }(());
60	
61	        (req_s, resp_r, terminator)
62	    }
63	
64	    init {  }
65	
66	    next(_: ()) {
67	        let tok = send(join(), req_s[0], ());
68	        let (tok, resp) = recv(tok, resp_r[0]);
69	        assert_eq(resp, u32:0b11111);
70	
71	        let tok = send(join(), req_s[1], ());
72	        let (tok, resp) = recv(tok, resp_r[1]);
73	        assert_eq(resp, u32:0b11111);
74	
75	        let tok = send(tok, terminator, true);
76	    }
77	}
