67	// Creates a stack trace for an interpreter error, starting with the top (most
68	// immediate) frame. The input is a call frame vector in bottom-to-top order,
69	// plus a span string indicating the DSLX node being evaluated when the error
70	// was encountered, which this function includes in the returned string as the
71	// bottom of the stack. Note that currently `Frame::initial_args()` is
72	// unreliable due to deeper problems than just not being populated in some
73	// cases, so we don't try to display the arguments.
74	std::string CallStackToString(std::string_view root_span_string,
75	                              const std::vector<const Frame*>& frames) {
76	  std::string result;
77	  for (int i = frames.size() - 1; i >= 0; --i) {
78	    const Frame* next = frames[i];
79	    if (i == 0 && next->bf()->source_fn() == nullptr) {
80	      break;
81	    }
82	    absl::StrAppendFormat(&result, "in %s\n",
83	                          next->bf()->source_fn() == nullptr
84	                              ? "<unknown>"
85	                              : next->bf()->source_fn()->identifier());
86	  }
87	  absl::StrAppendFormat(&result, "from %s", root_span_string);
88	  return result;
89	}
