93	/* static */ absl::Status ConstexprEvaluator::Evaluate(
94	    ImportData* import_data, TypeInfo* type_info,
95	    WarningCollector* warning_collector, const ParametricEnv& bindings,
96	    const Expr* expr, const Type* type, bool warn_rollover) {
97	  VLOG(5) << "ConstexprEvaluator::Evaluate; expr: " << expr->ToString() << " @ "
98	          << expr->span().ToString(import_data->file_table());
99	  if (type != nullptr) {
100	    XLS_RET_CHECK(!type->IsMeta());
101	  }
102	
103	  if (type_info->IsKnownConstExpr(expr) ||
104	      type_info->IsKnownNonConstExpr(expr)) {
105	    return absl::OkStatus();
106	  }
107	  ConstexprEvaluator evaluator(import_data, type_info, warning_collector,
108	                               bindings, type, warn_rollover);
109	  return expr->AcceptExpr(&evaluator);
110	}
