112	/* static */ absl::StatusOr<InterpValue> ConstexprEvaluator::EvaluateToValue(
113	    ImportData* import_data, TypeInfo* type_info,
114	    WarningCollector* warning_collector, const ParametricEnv& bindings,
115	    const Expr* expr, bool warn_rollover) {
116	  XLS_RETURN_IF_ERROR(Evaluate(import_data, type_info, warning_collector,
117	                               bindings, expr, nullptr, warn_rollover));
118	  if (type_info->IsKnownConstExpr(expr)) {
119	    return type_info->GetConstExpr(expr);
120	  }
121	  const FileTable& file_table = import_data->file_table();
122	  return NotConstantErrorStatus(expr->span(), expr, file_table);
123	}
124	
125	// Evaluates the given expression and terminates current function execution
126	// if it is not constexpr.
127	#define EVAL_AS_CONSTEXPR_OR_RETURN(EXPR)                                     \
128	  if (!type_info_->IsKnownConstExpr(EXPR) &&                                  \
129	      !type_info_->IsKnownNonConstExpr(EXPR)) {                               \
130	    Type* sub_type = nullptr;                                                 \
131	    if (type_info_->GetItem(EXPR).has_value()) {                              \
132	      sub_type = type_info_->GetItem(EXPR).value();                           \
133	    }                                                                         \
134	    ConstexprEvaluator sub_eval(import_data_, type_info_, warning_collector_, \
135	                                bindings_, sub_type, warn_rollover_);         \
136	    XLS_RETURN_IF_ERROR(EXPR->AcceptExpr(&sub_eval));                         \
137	  }                                                                           \
138	  if (!type_info_->IsKnownConstExpr(EXPR)) {                                  \
139	    return absl::OkStatus();                                                  \
140	  }
141	
142	// Assigns the constexpr value of the given expression to the LHS or terminates
143	// execution if it's not constexpr.
144	#define GET_CONSTEXPR_OR_RETURN(LHS, EXPR) \
145	  EVAL_AS_CONSTEXPR_OR_RETURN(EXPR);       \
146	  LHS = type_info_->GetConstExpr(EXPR).value();
