153	absl::Status ConstexprEvaluator::HandleZeroMacro(const ZeroMacro* expr) {
154	  const FileTable& file_table = *expr->owner()->file_table();
155	  ExprOrType type_reference = expr->type();
156	  std::optional<Type*> maybe_type =
157	      type_info_->GetItem(ToAstNode(type_reference));
158	  if (!maybe_type.has_value()) {
159	    std::optional<Span> span = ToAstNode(type_reference)->GetSpan();
160	    std::string span_str =
161	        span.has_value() ? span->ToString(file_table) : "<none>";
162	    return absl::InternalError(
163	        absl::StrFormat("Could not find type for \"%s\" @ %s",
164	                        ToAstNode(type_reference)->ToString(), span_str));
165	  }
166	
167	  XLS_ASSIGN_OR_RETURN(
168	      std::unique_ptr<Type> type,
169	      UnwrapMetaType(maybe_type.value()->CloneToUnique(), expr->span(),
170	                     "zero macro input type", file_table));
171	
172	  // At this point type inference should have checked that this type was
173	  // zero-able.
174	  XLS_ASSIGN_OR_RETURN(InterpValue value,
175	                       MakeZeroValue(*type, *import_data_, expr->span()));
176	  type_info_->NoteConstExpr(expr, value);
177	  return absl::OkStatus();
178	}
