224	absl::Status ConstexprEvaluator::HandleStatementBlock(
225	    const StatementBlock* expr) {
226	  bool all_statements_constexpr = true;
227	  Expr* last_expr = nullptr;
228	  for (Statement* stmt : expr->statements()) {
229	    if (!std::holds_alternative<Expr*>(stmt->wrapped())) {
230	      continue;
231	    }
232	    Expr* body_expr = std::get<Expr*>(stmt->wrapped());
233	    XLS_RETURN_IF_ERROR(body_expr->AcceptExpr(this));
234	    if (type_info_->IsKnownConstExpr(body_expr)) {
235	      last_expr = body_expr;
236	      type_info_->NoteConstExpr(body_expr,
237	                                type_info_->GetConstExpr(body_expr).value());
238	    } else {
239	      VLOG(10) << "ConstexprEvaluator::HandleBlock; expr was not constexpr: "
240	               << body_expr->ToString();
241	      all_statements_constexpr = false;
242	    }
243	  }
244	  if (all_statements_constexpr) {
245	    if (expr->trailing_semi()) {
246	      type_info_->NoteConstExpr(expr, InterpValue::MakeUnit());
247	    } else {
248	      type_info_->NoteConstExpr(expr,
249	                                type_info_->GetConstExpr(last_expr).value());
250	    }
251	  }
252	  return absl::OkStatus();
253	}
