261	// While a channel's *contents* aren't constexpr, the existence of the channel
262	// itself is.
263	absl::Status ConstexprEvaluator::HandleChannelDecl(const ChannelDecl* expr) {
264	  VLOG(3) << "ConstexprEvaluator::HandleChannelDecl : " << expr->ToString();
265	  const FileTable& file_table = *expr->owner()->file_table();
266	  // Keep in mind that channels come in tuples, so peel out the first element.
267	  std::optional<Type*> maybe_decl_type = type_info_->GetItem(expr);
268	  if (!maybe_decl_type.has_value()) {
269	    return absl::InternalError(
270	        absl::StrFormat("Could not find type for expr \"%s\" @ %s",
271	                        expr->ToString(), expr->span().ToString(file_table)));
272	  }
273	
274	  auto* tuple_type = dynamic_cast<TupleType*>(maybe_decl_type.value());
275	  if (tuple_type == nullptr) {
276	    return TypeInferenceErrorStatus(
277	        expr->span(), maybe_decl_type.value(),
278	        "Channel decl did not have tuple type:", file_table);
279	  }
280	
281	  // Verify that the channel tuple has exactly two elements; just yank one out
282	  // for channel [array] creation (they both point to the same object).
283	  if (tuple_type->size() != 2) {
284	    return TypeInferenceErrorStatus(expr->span(), tuple_type,
285	                                    "ChannelDecl type was a two-element tuple.",
286	                                    file_table);
287	  }
288	
289	  XLS_ASSIGN_OR_RETURN(
290	      auto in_out_channels,
291	      CreateChannelReferencePair(&tuple_type->GetMemberType(0)));
292	  type_info_->NoteConstExpr(
293	      expr,
294	      InterpValue::MakeTuple({in_out_channels.first, in_out_channels.second}));
295	  return absl::OkStatus();
296	}
