310	absl::Status ConstexprEvaluator::HandleIndex(const Index* expr) {
311	  VLOG(3) << "ConstexprEvaluator::HandleIndex : " << expr->ToString();
312	  EVAL_AS_CONSTEXPR_OR_RETURN(expr->lhs());
313	
314	  if (std::holds_alternative<Expr*>(expr->rhs())) {
315	    EVAL_AS_CONSTEXPR_OR_RETURN(std::get<Expr*>(expr->rhs()));
316	  } else if (std::holds_alternative<Slice*>(expr->rhs())) {
317	    Slice* slice = std::get<Slice*>(expr->rhs());
318	    if (slice->start() != nullptr) {
319	      EVAL_AS_CONSTEXPR_OR_RETURN(slice->start());
320	    }
321	    if (slice->limit() != nullptr) {
322	      EVAL_AS_CONSTEXPR_OR_RETURN(slice->limit());
323	    }
324	  } else {
325	    WidthSlice* width_slice = std::get<WidthSlice*>(expr->rhs());
326	    EVAL_AS_CONSTEXPR_OR_RETURN(width_slice->start());
327	  }
328	
329	  return InterpretExpr(expr);
330	}
