332	absl::Status ConstexprEvaluator::HandleInvocation(const Invocation* expr) {
333	  std::optional<std::string_view> called_name;
334	  auto* callee_name_ref = dynamic_cast<NameRef*>(expr->callee());
335	  if (callee_name_ref != nullptr) {
336	    called_name = callee_name_ref->identifier();
337	    if (called_name == "send" || called_name == "send_if" ||
338	        called_name == "recv" || called_name == "recv_if" ||
339	        called_name == "recv_non_blocking" ||
340	        called_name == "recv_if_non_blocking") {
341	      // I/O operations are never constexpr.
342	      return absl::OkStatus();
343	    }
344	  }
345	
346	  if (called_name == "map") {
347	    // Map "invocations" are special - only the first (of two) args must be
348	    // constexpr (the second must be a fn to apply).
349	    EVAL_AS_CONSTEXPR_OR_RETURN(expr->args()[0])
350	  } else {
351	    // A regular invocation is constexpr iff its args are constexpr.
352	    for (const auto* arg : expr->args()) {
353	      EVAL_AS_CONSTEXPR_OR_RETURN(arg)
354	    }
355	  }
356	
357	  // We don't [yet] have a static assert fn, meaning that we don't want to catch
358	  // runtime errors here. If we detect that a program has failed (due to
359	  // execution of a `fail!` or unmatched `match`, then just assume we're ok.
360	  absl::Status status = InterpretExpr(expr);
361	  if (!status.ok() && !absl::StartsWith(status.message(), "FailureError")) {
362	    return status;
363	  }
364	
365	  return absl::OkStatus();
366	}
