391	absl::Status ConstexprEvaluator::HandleNameRef(const NameRef* expr) {
392	  if (std::holds_alternative<const NameDef*>(expr->name_def())) {
393	    auto* name_def = std::get<const NameDef*>(expr->name_def());
394	    if (auto* use_tree_entry = dynamic_cast<UseTreeEntry*>(name_def->definer());
395	        use_tree_entry != nullptr) {
396	      return HandleExternRef(expr, name_def, use_tree_entry);
397	    }
398	  }
399	
400	  AstNode* name_def = ToAstNode(expr->name_def());
401	
402	  if (type_info_->IsKnownNonConstExpr(name_def) ||
403	      !type_info_->IsKnownConstExpr(name_def)) {
404	    return absl::OkStatus();
405	  }
406	  type_info_->NoteConstExpr(expr, type_info_->GetConstExpr(name_def).value());
407	  return absl::OkStatus();
408	}
