410	absl::StatusOr<InterpValue> EvaluateNumber(const Number& expr,
411	                                           const Type& type) {
412	  const FileTable& file_table = *expr.owner()->file_table();
413	  XLS_RET_CHECK(!type.IsMeta())
414	      << "Got invalid type when evaluating number: " << type.ToString() << " @ "
415	      << expr.span().ToString(file_table);
416	  VLOG(4) << "Evaluating number: " << expr.ToString() << " @ "
417	          << expr.span().ToString(file_table);
418	
419	  std::optional<BitsLikeProperties> bits_like = GetBitsLike(type);
420	
421	  XLS_RET_CHECK(bits_like.has_value())
422	      << "Type for number should be bits-like; got: " << type;
423	
424	  XLS_ASSIGN_OR_RETURN(bool is_signed, bits_like->is_signed.GetAsBool());
425	
426	  InterpValueTag tag =
427	      is_signed ? InterpValueTag::kSBits : InterpValueTag::kUBits;
428	
429	  const InterpValue& value = bits_like->size.value();
430	  XLS_ASSIGN_OR_RETURN(int64_t bit_count, value.GetBitValueViaSign());
431	
432	  XLS_ASSIGN_OR_RETURN(Bits bits, expr.GetBits(bit_count, file_table));
433	  return InterpValue::MakeBits(tag, std::move(bits));
434	}
