436	absl::Status ConstexprEvaluator::HandleNumber(const Number* expr) {
437	  // Numbers should always be [constexpr] evaluatable.
438	  XLS_ASSIGN_OR_RETURN(ConstexprEnvData constexpr_env_data,
439	                       MakeConstexprEnv(import_data_, type_info_,
440	                                        warning_collector_, expr, bindings_));
441	  XLS_RET_CHECK(constexpr_env_data.non_constexpr.empty());
442	
443	  std::unique_ptr<BitsType> temp_type;
444	  const Type* type_ptr;
445	  if (expr->type_annotation() != nullptr) {
446	    // If the number is annotated with a type, then extract it to pass to
447	    // EvaluateNumber (for consistency checking). It might be that the type is
448	    // parametric, in which case we'll need to fully instantiate it.
449	    auto maybe_type_ptr = type_info_->GetItem(expr->type_annotation());
450	    XLS_RET_CHECK(maybe_type_ptr.has_value());
451	    const MetaType* tt = dynamic_cast<const MetaType*>(maybe_type_ptr.value());
452	    XLS_RET_CHECK(tt != nullptr);
453	    type_ptr = tt->wrapped().get();
454	
455	    std::optional<BitsLikeProperties> bits_like = GetBitsLike(*type_ptr);
456	    XLS_RET_CHECK(bits_like.has_value())
457	        << "Type for number should be bits-like; got: " << type_ptr->ToString();
458	
459	    // Materialize the bits type.
460	    XLS_ASSIGN_OR_RETURN(bool is_signed, bits_like->is_signed.GetAsBool());
461	    XLS_ASSIGN_OR_RETURN(int64_t bit_count, bits_like->size.GetAsInt64());
462	    temp_type = std::make_unique<BitsType>(is_signed, bit_count);
463	    type_ptr = temp_type.get();
464	  } else if (type_ != nullptr) {
465	    type_ptr = type_;
466	  } else if (expr->number_kind() == NumberKind::kBool) {
467	    temp_type = std::make_unique<BitsType>(false, 1);
468	    type_ptr = temp_type.get();
469	  } else if (expr->number_kind() == NumberKind::kCharacter) {
470	    temp_type = std::make_unique<BitsType>(false, 8);
471	    type_ptr = temp_type.get();
472	  } else {
473	    // "Undecorated" numbers that make it through typechecking are `usize`,
474	    // which currently is u32.
475	    temp_type = std::make_unique<BitsType>(false, 32);
476	    type_ptr = temp_type.get();
477	  }
478	
479	  XLS_RET_CHECK(type_ptr != nullptr);
480	  XLS_ASSIGN_OR_RETURN(InterpValue value, EvaluateNumber(*expr, *type_ptr));
481	  type_info_->NoteConstExpr(expr, value);
482	
483	  return absl::OkStatus();
484	}
