517	absl::Status ConstexprEvaluator::HandleConditional(const Conditional* expr) {
518	  // Simple enough that we don't need to invoke the interpreter.
519	  EVAL_AS_CONSTEXPR_OR_RETURN(expr->test());
520	  EVAL_AS_CONSTEXPR_OR_RETURN(expr->consequent());
521	  EVAL_AS_CONSTEXPR_OR_RETURN(ToExprNode(expr->alternate()));
522	
523	  InterpValue test = type_info_->GetConstExpr(expr->test()).value();
524	  if (test.IsTrue()) {
525	    type_info_->NoteConstExpr(
526	        expr, type_info_->GetConstExpr(expr->consequent()).value());
527	  } else {
528	    type_info_->NoteConstExpr(
529	        expr, type_info_->GetConstExpr(ToExprNode(expr->alternate())).value());
530	  }
531	
532	  return absl::OkStatus();
533	}
