541	absl::Status ConstexprEvaluator::HandleTupleIndex(const TupleIndex* expr) {
542	  // No need to fire up the interpreter. This one is easy.
543	  GET_CONSTEXPR_OR_RETURN(InterpValue tuple, expr->lhs());
544	  GET_CONSTEXPR_OR_RETURN(InterpValue index, expr->index());
545	
546	  XLS_ASSIGN_OR_RETURN(uint64_t index_value, index.GetBitValueUnsigned());
547	  XLS_ASSIGN_OR_RETURN(const std::vector<InterpValue>* values,
548	                       tuple.GetValues());
549	  if (index_value < 0 || index_value > values->size()) {
550	    const FileTable& file_table = *expr->owner()->file_table();
551	    return absl::InvalidArgumentError(absl::StrFormat(
552	        "%s: Out-of-range tuple index: %d vs %d.",
553	        expr->span().ToString(file_table), index_value, values->size()));
554	  }
555	  type_info_->NoteConstExpr(expr, values->at(index_value));
556	  return absl::OkStatus();
557	}
558	
559	absl::Status ConstexprEvaluator::HandleConstFor(const ConstFor* expr) {
560	  std::optional<const Expr*> unrolled =
561	      type_info_->GetUnrolledLoop(expr, bindings_);
562	  if (unrolled.has_value()) {
563	    return (*unrolled)->AcceptExpr(this);
564	  }
565	  return absl::OkStatus();
566	}
567	
568	absl::Status ConstexprEvaluator::HandleVerbatimNode(const VerbatimNode* node) {
569	  return absl::UnimplementedError("Should not evaluate VerbatimNode");
570	}
571	
572	absl::Status ConstexprEvaluator::HandleXlsTuple(const XlsTuple* expr) {
573	  std::vector<InterpValue> values;
574	  for (const Expr* member : expr->members()) {
575	    GET_CONSTEXPR_OR_RETURN(InterpValue value, member);
576	    values.push_back(value);
577	  }
578	
579	  // No need to fire up the interpreter. We can handle this one.
580	  type_info_->NoteConstExpr(expr, InterpValue::MakeTuple(values));
581	  return absl::OkStatus();
582	}
583	
584	absl::Status ConstexprEvaluator::InterpretExpr(const Expr* expr) {
585	  XLS_ASSIGN_OR_RETURN(ConstexprEnvData constexpr_env_data,
586	                       MakeConstexprEnv(import_data_, type_info_,
587	                                        warning_collector_, expr, bindings_));
588	
589	  XLS_ASSIGN_OR_RETURN(
590	      std::unique_ptr<BytecodeFunction> bf,
591	      BytecodeEmitter::EmitExpression(import_data_, type_info_, expr,
592	                                      constexpr_env_data.env, bindings_));
593	
594	  // TODO(williamjhuang) - The previous code has a bug here that
595	  // BytecodeInterpreter does not uses the rollover_hook even one is intended to
596	  // be used. In TIv1 this ended up only implicit parametric bindings are being
597	  // checked for rollover in a different code path, but not at other location
598	  // where constexpr is expected. We are matching this behavior in TIv2 for now
599	  // because a lot of code in stdlib has potentially overflowing immediate
600	  // expressions, so we cannot enable this warning universally.
601	  BytecodeInterpreterOptions options;
602	  if (warning_collector_ && warn_rollover_) {
603	    options.rollover_hook([&](RolloverEvent e) {
604	      warning_collector_->Add(
605	          e.span, WarningKind::kConstexprEvalRollover,
606	          absl::Substitute("constexpr evaluation detected rollover in "
607	                           "operation with left-hand value `$0` and right-hand "
608	                           "value `$1`\n$2",
609	                           e.lhs.ToString(/*humanize=*/true),
610	                           e.rhs.ToString(/*humanize=*/true),
611	                           CallStackToString(expr->span().ToString(
612	                                                 *expr->owner()->file_table()),
613	                                             e.frames)));
614	    });
615	  }
616	  XLS_ASSIGN_OR_RETURN(
617	      InterpValue constexpr_value,
618	      BytecodeInterpreter::Interpret(
619	          import_data_, bf.get(),
620	          /*args=*/{}, /*channel_manager=*/std::nullopt, options));
621	  type_info_->NoteConstExpr(expr, constexpr_value);
622	
623	  return absl::OkStatus();
624	}
625	
626	absl::StatusOr<ConstexprEnvData> MakeConstexprEnv(
627	    ImportData* import_data, TypeInfo* type_info,
628	    WarningCollector* warning_collector, const Expr* node,
629	    const ParametricEnv& parametric_env) {
630	  VLOG(5) << "Creating constexpr environment for node: `" << node->ToString()
631	          << "`";
632	
633	  // The constexpr environment we'll build up as we walk the free variables.
634	  absl::flat_hash_map<std::string, InterpValue> env;
635	
636	  // Seed the constexpr environment with parametric bindings.
637	  //
638	  // Implementation note: we could instead have this function expect to resolve
639	  // all of these via `type_info`, but being able to take the `parametric_env`
640	  // and use that for initial population allows us to pass in partially built
641	  // parametric results, e.g. in parametric instantiation, without needing to
642	  // put everything we discover immediately into the type info.
643	  for (const auto& [id, value] : parametric_env.ToMap()) {
644	    env.insert({id, value});
645	  }
646	
647	  // Collect all the freevars that are constexpr.
648	  FreeVariables freevars = GetFreeVariablesByPos(node);
649	  VLOG(5) << absl::StreamFormat("free variables for `%s`: %s", node->ToString(),
650	                                freevars.ToString());
651	  freevars = freevars.DropBuiltinDefs();
652	
653	  // Keep track of which name references we could not resolve to be constexpr.
654	  absl::flat_hash_set<const NameRef*> non_constexpr;
655	
656	  for (const auto& [name, name_refs] : freevars.values()) {
657	#ifndef NDEBUG
658	    // Verify that all the name refs are referring to the same name def -- this
659	    // should be true of free variables for any lexical environment.
660	    for (int64_t i = 1; i < name_refs.size(); ++i) {
661	      DCHECK(name_refs[i]->name_def() == name_refs[0]->name_def());
662	    }
663	#endif
664	
665	    CHECK_GE(name_refs.size(), 1);
666	    // Note: we dropped all builtin defs above so this variant access should be
667	    // safe/correct.
668	    const NameRef* sample_ref = name_refs.front();
669	    const NameDef* target_def =
670	        std::get<const NameDef*>(sample_ref->name_def());
671	
672	    XLS_RETURN_IF_ERROR(
673	        ConstexprEvaluator::Evaluate(import_data, type_info, warning_collector,
674	                                     parametric_env, sample_ref, nullptr));
675	    absl::StatusOr<InterpValue> const_expr =
676	        type_info->GetConstExpr(target_def);
677	    if (const_expr.ok()) {
678	      env.insert({name, const_expr.value()});
679	    } else {
680	      non_constexpr.insert(sample_ref);
681	    }
682	  }
683	
684	  return ConstexprEnvData{
685	      .freevars = freevars,
686	      .env = env,
687	      .non_constexpr = non_constexpr,
688	  };
689	}
690	
691	std::string EnvMapToString(
692	    const absl::flat_hash_map<std::string, InterpValue>& map) {
693	  std::vector<const std::pair<const std::string, InterpValue>*> items;
694	  items.reserve(map.size());
695	  for (const auto& item : map) {
696	    items.push_back(&item);
697	  }
698	  std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
699	    return a->first < b->first;  // Order by key.
700	  });
701	  std::string guts =
702	      absl::StrJoin(items, ", ", [](std::string* out, const auto& item) {
703	        absl::StrAppend(out, item->first, ": ", item->second.ToString());
704	      });
705	  return absl::StrCat("{", guts, "}");
706	}
707	
708	absl::StatusOr<std::string> EvaluateFormatString(
709	    ImportData* import_data, TypeInfo* type_info,
710	    WarningCollector* warning_collector, const ParametricEnv& parametric_env,
711	    const std::vector<FormatStep>& steps, absl::Span<Expr* const> args) {
712	  std::string result;
713	  int64_t arg_i = 0;
714	  for (const FormatStep& step : steps) {
715	    if (std::holds_alternative<std::string>(step)) {
716	      absl::StrAppend(&result, std::get<std::string>(step));
717	    } else {
718	      FormatPreference preference = std::get<FormatPreference>(step);
719	      Expr* arg = args[arg_i++];
720	      XLS_ASSIGN_OR_RETURN(
721	          InterpValue value,
722	          ConstexprEvaluator::EvaluateToValue(
723	              import_data, type_info, warning_collector, parametric_env, arg));
724	      XLS_ASSIGN_OR_RETURN(std::string formatted,
725	                           FormatInterpValue(value, preference));
726	      absl::StrAppend(&result, formatted);
727	    }
728	  }
729	  return result;
730	}
731	
732	}  // namespace xls::dslx
